contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0);
        require(amount_ <= type(uint256).max / (10 ** c.collateral().decimals()));

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        uint256 count = getRequestsLength();
        require(count > 0);

        (uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, bool active) = getRequest(reqID);

        assert(
            reqID == count - 1 &&
            amount == amount_ &&
            interest == interest_ &&
            loanToCollateral == loanToCollateral_ &&
            duration == duration_ &&
            active
        );
    }

    function getRequestsLength() internal view returns (uint256 len) {
        uint256 i = 0;
        while (true) {
            try c.requests(i) returns (uint256, uint256, uint256, uint256, bool) {
                i++;
            } catch {
                return i;
            }
        }
    }

    function getRequest(uint256 reqID_) internal view returns (uint256, uint256, uint256, uint256, bool) {
        return c.getRequest(reqID_);
    }

    receive() external payable {}
}

