contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        uint256 reqID_
    ) public {
        require(loanToCollateral_ != 0);
        require(amount_ <= type(uint128).max);
        require(loanToCollateral_ <= type(uint128).max);

        bool ownerIsSender = (msg.sender == c.owner());

        uint256 reqCountBefore = c.requests.length;

        bool activeBefore;
        if (reqID_ < reqCountBefore) {
            activeBefore = c.isActive(reqID_);
        }

        bool reverted;
        try c.rescindRequest(reqID_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool expectSuccess = ownerIsSender && !reverted;

        if (!expectSuccess) {
            assert(reverted);
        } else {
            bool activeAfter = c.isActive(reqID_);
            assert(!activeAfter);
        }
    }
}

