contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 requestAmount,
        uint256 interestRate,
        uint256 loanToCollateral,
        uint256 duration,
        uint256 fundAmount,
        uint256 repayAmount
    ) public payable {
        require(loanToCollateral >= 1, "loanToCollateral zero");
        require(requestAmount >= 1, "requestAmount zero");

        // Fund this contract with debt tokens so it can clear the request.
        require(c.debt().balanceOf(address(this)) >= requestAmount, "insufficient debt token balance");

        c.requestLoan(requestAmount, interestRate, loanToCollateral, duration);

        uint256 loanID = c.clearRequest(0, true, false);

        C.Loan memory farBefore = c.getLoan(loanID);
        uint256 collateralBefore = farBefore.collateral;
        uint256 amountBefore = farBefore.amount;
        uint256 ownerBefore = c.owner().balance;

        uint256 decollateralized;
        bool reverted;
        try c.repayLoan(loanID, repayAmount) returns (uint256 r) {
            decollateralized = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted ||
            (
                decollateralized <= collateralBefore &&
                c.getLoan(loanID).collateral == collateralBefore - decollateralized &&
                decollateralized == (collateralBefore * (repayAmount > amountBefore ? amountBefore : repayAmount)) / amountBefore
            )
        );
    }
}

