contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        uint256 repaid_
    ) public payable {
        require(loanToCollateral_ > 0);
        require(amount_ > 0);
        require(duration_ > 0);

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_);
        c.clearRequest(0, true, false);

        bool reverted;
        uint256 ret;
        try c.repayLoan(0, repaid_) returns (uint256 r) {
            ret = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        C.Loan memory loanBefore = c.getLoan(0);
        uint256 collat = c.collateralFor(amount_, loanToCollateral_);

        if (block.timestamp > loanBefore.expiry || (collat * repaid_) / loanBefore.amount == 0) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(ret == (collat * (repaid_ > loanBefore.amount ? loanBefore.amount : repaid_)) / loanBefore.amount);
        }
    }

    receive() external payable {}
}

